  let i = 0;
  let digits = "";

  let k: bigint = 0n;
  let k1: bigint = 1n;
  let a: bigint = 0n;
  let d: bigint = 1n;
  let m: bigint = 0n;
  let n: bigint = 1n;
  let t: bigint = 0n;
  let u: bigint = 1n;

